const uint16_t g_chinese_font_count = 276;

const uint8_t* LCD_GetChineseFont16(uint32_t unicode)
{
    int low = 0;
    int high = g_chinese_font_count - 1;
    while (low <= high)
    {
        int mid = (low + high) / 2;
        if (g_chinese_font_1616[mid].unicode == unicode)
        {
            return g_chinese_font_1616[mid].bitmap;
        }
        else if (g_chinese_font_1616[mid].unicode < unicode)
        {
            low = mid + 1;
        }
        else
        {
            high = mid - 1;
        }
    }
    return 0;
}
